<!DOCTYPE html>
<html lang="id">
<head>
    <meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Laporan | Asrama Putri Junjung Buyah Kukar YK</title>
    <style>
        :root { --ink: #171717; --muted: #737373; --line: #e3e3e3; --soft: #fafafa; --yellow: #ffe51f; --green: #078455; --red: #b42318; --blue: #075fd8; }
        * { box-sizing: border-box; } body { margin: 0; color: var(--ink); background: #fff; font-family: Inter, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif; } a { color: inherit; text-decoration: none; } button, input { font: inherit; }
        .topbar { height: 54px; display: flex; align-items: center; justify-content: space-between; gap: 24px; padding: 0 15px; border-bottom: 1px solid var(--line); } .brand { display: flex; align-items: center; gap: 9px; color: var(--muted); font-size: 14px; white-space: nowrap; } .brand img { width: 27px; height: 27px; border-radius: 50%; object-fit: cover; } .brand strong { color: var(--ink); } .top-search, .search { display: flex; align-items: center; gap: 10px; border: 1px solid var(--line); border-radius: 7px; color: #999; background: #fff; } .top-search { width: min(385px, 34vw); padding: 8px 11px; } .top-search input, .search input { width: 100%; border: 0; outline: 0; color: var(--ink); background: transparent; font-size: 13px; } .shortcut { padding: 3px 7px; border: 1px solid var(--line); border-radius: 4px; font-size: 10px; } .top-actions { display: flex; align-items: center; gap: 8px; } .back-dashboard { padding: 9px 13px; border: 1px solid var(--line); border-radius: 7px; color: var(--ink); background: #fff; font-size: 12px; font-weight: 700; } .icon-button { width: 37px; height: 37px; border: 1px solid var(--line); border-radius: 7px; color: var(--muted); background: #fff; }
        main { max-width: 1650px; margin: auto; padding: 29px 22px 60px; } h1 { margin: 0; font-size: 25px; letter-spacing: -.04em; } .intro { margin: 7px 0 25px; color: var(--muted); font-size: 14px; } .filters { display: flex; align-items: end; gap: 16px; margin-bottom: 24px; padding: 20px; border: 1px solid var(--line); border-radius: 6px; } .filter-field { display: grid; gap: 7px; } .filter-field label { color: #666; font-size: 10px; font-weight: 800; text-transform: uppercase; } .filter-field input { width: 153px; padding: 10px 12px; border: 1px solid #d8d8d8; border-radius: 7px; outline: 0; font-size: 13px; } .filters .search { width: 290px; padding: 10px 12px; } .filter-button { padding: 10px 13px; border: 1px solid var(--line); border-radius: 7px; color: #555; background: #fff; font-size: 12px; cursor: pointer; } .filter-button.green { border-color: var(--green); color: #fff; background: var(--green); }
        .panel { overflow: hidden; border: 1px solid var(--line); border-radius: 6px; } .panel-top { display: flex; align-items: center; justify-content: space-between; gap: 20px; padding: 15px 20px; border-bottom: 1px solid #f0f0f0; } .tabs { display: flex; gap: 4px; padding: 4px; border: 1px solid var(--line); border-radius: 7px; } .tab { padding: 9px 16px; border: 0; border-radius: 5px; color: #555; background: transparent; font-size: 12px; cursor: pointer; } .tab.active { color: #fff; background: var(--ink); font-weight: 800; } .count { color: var(--muted); font-size: 12px; }
        .table-wrap { overflow-x: auto; } table { width: 100%; min-width: 1100px; border-collapse: collapse; } th, td { padding: 14px 20px; border-bottom: 1px solid #eeeeee; text-align: left; vertical-align: middle; } th { color: #626262; background: #fcfcfc; font-size: 10px; letter-spacing: .12em; text-transform: uppercase; white-space: nowrap; } td { color: #555; font-size: 13px; } tbody tr:hover { background: #fffef3; } tbody tr:last-child td { border-bottom: 0; } .date { color: #777; white-space: nowrap; } .transaction { color: var(--blue); font-size: 11px; font-weight: 800; } .resident { color: var(--ink); font-weight: 700; } .room { min-width: 230px; } .method { display: inline-flex; padding: 5px 10px; border: 1px solid #add4ff; border-radius: 99px; color: var(--blue); background: #f0f7ff; font-size: 10px; font-weight: 800; white-space: nowrap; } .method.cash { border-color: #ffd76a; color: #ad6500; background: #fffaf0; } .method.manual { border-color: #ddd; color: #666; background: #fafafa; } .total { color: var(--ink); font-weight: 800; text-align: right; white-space: nowrap; } .in { color: var(--green) !important; font-weight: 800; } .out { color: var(--red) !important; font-weight: 800; } .empty { padding: 45px; color: var(--muted); text-align: center; } .summary { display: flex; align-items: center; gap: 15px; padding: 15px 20px; border-top: 1px solid var(--line); } .summary strong { font-size: 17px; } .summary span { padding-left: 15px; border-left: 1px solid #ccc; color: var(--muted); font-size: 12px; }
        @media print { .topbar, .filters, .intro { display: none !important; } main { max-width: none; padding: 0; } h1 { margin-bottom: 18px; text-align: center; } .panel { border: 0; } .panel-top { border: 0; } .tabs, .count { display: none; } table { min-width: 0; } th, td { padding: 9px 10px; } .summary { margin-top: 18px; border: 1px solid var(--line); } }
        @media (max-width: 850px) { .top-search { display: none; } .filters { align-items: stretch; flex-wrap: wrap; } .filters .search { width: 100%; } .filter-field, .filter-field input { flex: 1; width: auto; } } @media (max-width: 550px) { .topbar { padding: 0 12px; } main { padding: 24px 14px; } .panel-top { align-items: flex-start; flex-direction: column; } .tabs { width: 100%; } .tab { flex: 1; } .summary { align-items: flex-start; flex-direction: column; } .summary span { padding: 0; border: 0; } }
        html[data-theme="dark"] body { color: #f4f4f4; background: #111; } html[data-theme="dark"] .topbar, html[data-theme="dark"] .filters, html[data-theme="dark"] .panel { background: #191919; border-color: #333; } html[data-theme="dark"] .top-search, html[data-theme="dark"] .search, html[data-theme="dark"] .icon-button, html[data-theme="dark"] .filter-button { color: #eee; background: #191919; border-color: #444; } html[data-theme="dark"] input { color: #eee; background: #222; border-color: #444; } html[data-theme="dark"] th { background: #202020; } html[data-theme="dark"] td, html[data-theme="dark"] th { border-color: #333; } html[data-theme="dark"] .brand strong, html[data-theme="dark"] h1 { color: #fff; }
        :root { --ink: #17201d; --muted: #68736f; --line: #e5e9e6; --soft: #f7f9f6; }
        body { background: radial-gradient(circle at 90% 0, #e9f7c8 0, transparent 28%), #f4f7f3; } .topbar { position: sticky; top: 0; z-index: 4; height: 68px; padding: 0 34px; background: rgba(255,255,255,.9); backdrop-filter: blur(16px); } main { max-width: 1560px; padding: 42px 34px 70px; } .filters, .panel { border-radius: 16px; box-shadow: 0 14px 40px rgba(23,32,29,.07); } th { background: #fbfcfa; color: #68736f; } td { color: #34413c; } tbody tr:hover { background: #f7faed; }
        html[data-theme="dark"] body { color: #f3f7f4; background: #101412; } html[data-theme="dark"] .topbar, html[data-theme="dark"] .filters, html[data-theme="dark"] .panel { background: #1a211e; border-color: #35413b; } html[data-theme="dark"] th { color: #dce7e0; background: #26312b; border-color: #405047; } html[data-theme="dark"] td { color: #d7e1da; border-color: #35413b; } html[data-theme="dark"] tbody tr:hover { background: #29362d; } html[data-theme="dark"] h1, html[data-theme="dark"] .brand strong { color: #f3f7f4; } html[data-theme="dark"] input, html[data-theme="dark"] .search, html[data-theme="dark"] .filter-button { color: #f3f7f4; background: #202923; border-color: #4a5a50; }
        main { max-width: 1560px; padding: 42px 34px 70px; }
        main > h1 { font-size: clamp(28px, 3vw, 36px); letter-spacing: -.06em; }
        .filters { align-items: end; flex-wrap: wrap; gap: 10px; margin-bottom: 18px; padding: 16px 18px; border-radius: 16px; background: rgba(255,255,255,.82); box-shadow: 0 14px 40px rgba(23,32,29,.07); }
        .filter-field { min-width: 145px; }
        .filter-field select, .filter-field input { width: 100%; min-height: 39px; }
        .filters .search { flex: 1 1 250px; width: auto; min-height: 39px; }
        .filter-button { min-height: 39px; border-radius: 9px; white-space: nowrap; }
        .panel { border-radius: 16px; box-shadow: 0 14px 40px rgba(23,32,29,.07); }
        .panel-top { min-height: 72px; padding: 16px 22px; }
        th, td { padding: 15px 20px; }
        html[data-theme="dark"] .filters { background: #1a211e; border-color: #35413b; }
        html[data-theme="dark"] .filter-field input, html[data-theme="dark"] .filter-field select { color: #f3f7f4; background: #202923; border-color: #4a5a50; }
    </style>
    <script>document.documentElement.dataset.theme = localStorage.getItem('admin-theme') || (matchMedia('(prefers-color-scheme: dark)').matches ? 'dark' : 'light');</script>
</head>
<body>
    <header class="topbar"><a class="brand" href="{{ route('admin.dashboard') }}"><img src="{{ asset('images/logo-siap-kukar.png') }}" alt="Logo Asrama Putri Junjung Buyah Kukar YK"><span>Asrama Putri Junjung Buyah Kukar YK</span><span>›</span><strong>Laporan</strong></a><div class="top-search"><span>⌕</span><input id="global-search" placeholder="Cari kamar, penghuni, pembayaran..."><span class="shortcut">Ctrl K</span></div><div class="top-actions"><a class="back-dashboard" href="{{ route('admin.dashboard') }}">Kembali ke Dashboard</a><button class="icon-button" type="button" aria-label="Notifikasi">♧</button><button class="icon-button" type="button" id="theme-toggle" aria-label="Ganti mode warna">☼</button></div></header>
    <main><h1>Laporan</h1><p class="intro">Rekap pemasukan, pengeluaran, dan cashflow dalam satu modul dengan filter periode dan pencarian.</p>
        <form class="filters" method="GET" action="{{ route('admin.laporan') }}"><div class="filter-field"><label>Periode Cepat</label><select name="periode"><option value="">Pilih periode</option><option value="bulan_ini">Bulan ini</option><option value="tahun_ini">Tahun ini</option></select></div><div class="filter-field"><label>Tgl Mulai</label><input type="date" name="mulai" value="{{ $mulai }}"></div><div class="filter-field"><label>Tgl Sampai</label><input type="date" name="sampai" value="{{ $sampai }}"></div><div class="search"><span>⌕</span><input name="search" value="{{ $search }}" placeholder="Cari transaksi, penghuni, keterangan..."></div><input type="hidden" name="jenis" value="{{ $jenis }}"><button class="filter-button" type="submit">Terapkan</button><a class="filter-button" href="{{ route('admin.laporan') }}">Reset</a><a class="filter-button" href="{{ route('admin.laporan.export.pdf', request()->query()) }}">Export PDF</a><a class="filter-button green" href="{{ route('admin.laporan.export.excel', request()->query()) }}">Export Excel</a><a class="filter-button" href="{{ route('admin.laporan.hunian') }}">Laporan Penghuni & Kamar</a></form>
        <section class="panel"><div class="panel-top"><div class="tabs"><a class="tab {{ $jenis === 'pemasukan' ? 'active' : '' }}" href="{{ route('admin.laporan', request()->except('jenis') + ['jenis' => 'pemasukan']) }}">Pemasukan</a><a class="tab {{ $jenis === 'pengeluaran' ? 'active' : '' }}" href="{{ route('admin.laporan', request()->except('jenis') + ['jenis' => 'pengeluaran']) }}">Pengeluaran</a><a class="tab {{ $jenis === 'cashflow' ? 'active' : '' }}" href="{{ route('admin.laporan', request()->except('jenis') + ['jenis' => 'cashflow']) }}">Cashflow</a></div><span class="count">Menampilkan {{ $transaksi->count() }} transaksi {{ $jenis }}.</span></div><div class="table-wrap"><table><thead><tr><th>Tanggal</th><th>No Pembayaran</th><th>Penghuni</th><th>Kamar</th><th>Metode</th><th>Kategori</th><th>Keterangan</th>@if ($jenis === 'cashflow')<th>Jenis Arus</th><th>Total</th>@else<th>Total {{ $jenis === 'pengeluaran' ? 'Pengeluaran' : 'Pemasukan' }}</th>@endif</tr></thead><tbody>@forelse ($transaksi as $item)<tr><td class="date">{{ $item->tanggal?->format('d M Y') }}</td><td class="transaction">{{ $item->pembayaran_id ? 'PAY-'.str_pad($item->pembayaran_id, 5, '0', STR_PAD_LEFT) : 'MAN-'.str_pad($item->id, 5, '0', STR_PAD_LEFT) }}</td><td class="resident">{{ $item->jenis_transaksi === 'pengeluaran' ? 'Bendahara' : ($item->pembayaran?->user?->name ?? '-') }}</td><td class="room">{{ $item->pembayaran?->user?->kamar?->nomor_kamar ? 'Kamar '.$item->pembayaran->user->kamar->nomor_kamar : ($item->pembayaran_id ? 'Belum Dialokasikan' : 'Transaksi Manual') }}</td><td><span class="method {{ $item->pembayaran?->metode_pembayaran === 'cash' ? 'cash' : ($item->pembayaran_id ? '' : 'manual') }}">{{ $item->pembayaran?->metode_pembayaran === 'cash' ? 'Cash' : ($item->pembayaran_id ? 'Transfer' : ($item->metode_pembayaran ? ucfirst($item->metode_pembayaran) : 'Manual')) }}</span></td><td>{{ $item->keterangan }}</td>@if ($jenis === 'cashflow')<td class="{{ $item->jenis_transaksi === 'pemasukan' ? 'in' : 'out' }}">{{ ucfirst($item->jenis_transaksi) }}</td><td class="total {{ $item->jenis_transaksi === 'pemasukan' ? 'in' : 'out' }}">{{ $item->jenis_transaksi === 'pemasukan' ? '+' : '-' }} Rp {{ number_format($item->nominal, 0, ',', '.') }}</td>@else<td class="total">Rp {{ number_format($item->nominal, 0, ',', '.') }}</td>@endif</tr>@empty<tr><td colspan="{{ $jenis === 'cashflow' ? 9 : 7 }}" class="empty">Belum ada transaksi {{ $jenis }}.</td></tr>@endforelse</tbody></table></div><div class="summary">@if ($jenis === 'cashflow')<strong class="in">Pemasukan: Rp {{ number_format($pemasukan, 0, ',', '.') }}</strong><strong class="out">Pengeluaran: Rp {{ number_format($pengeluaran, 0, ',', '.') }}</strong><strong>Saldo: Rp {{ number_format($pemasukan - $pengeluaran, 0, ',', '.') }}</strong>@else<strong>Total: Rp {{ number_format($jenis === 'pengeluaran' ? $pengeluaran : $pemasukan, 0, ',', '.') }}</strong>@endif<span>Periode: {{ $mulai ?: 'Semua' }} s/d {{ $sampai ?: 'Sekarang' }}</span><span>{{ $transaksi->count() }} transaksi</span></div></section>
    </main>
    <script>const globalSearch = document.querySelector('#global-search'); const reportSearch = document.querySelector('input[name="search"]'); globalSearch.addEventListener('input', () => { reportSearch.value = globalSearch.value; }); document.addEventListener('keydown', (event) => { if ((event.ctrlKey || event.metaKey) && event.key.toLowerCase() === 'k') { event.preventDefault(); globalSearch.focus(); } });</script>
<script>const themeToggle=document.querySelector('#theme-toggle');const setTheme=()=>{const dark=document.documentElement.dataset.theme==='dark';themeToggle.textContent=dark?'☀':'☾';themeToggle.onclick=()=>{const next=document.documentElement.dataset.theme==='dark'?'light':'dark';document.documentElement.dataset.theme=next;localStorage.setItem('admin-theme',next);themeToggle.textContent=next==='dark'?'☀':'☾';};};setTheme();</script></body>
</html>
